OI="INSERT INTO OrderItem (OrderItemID,OrderID,VariantID,BusinessID,Quantity,UnitPrice,LineTotal,DiscountAmount,TaxCategoryID,TaxRate,TaxAmount) VALUES"
OR="INSERT INTO Orders (OrderID,LocationID,BusinessID,ChannelCode,RegisterID,EmployeeID,Subtotal,Total) VALUES"
PY="INSERT INTO Payment (PaymentID,OrderID,PaymentMethodCode,Amount,PaymentStatusCode,GiftCardID) VALUES"
GC="INSERT INTO GiftCard (GiftCardID,BusinessID,CodeHash,Last4,OrderItemID) VALUES"
ADJ="INSERT INTO GiftCardTransaction (GiftCardTransactionID,GiftCardID,BusinessID,GiftCardTransactionTypeCode,Amount,EmployeeID,Reason) VALUES"
RF="INSERT INTO Refund (RefundID,PaymentID,ReturnID,OrderID,BusinessID,Amount,TaxAmount,Reason,RefundStatusCode,ApprovedByEmployeeID,CreatedBy,RefundDateTime) VALUES"
BAL="SELECT CONCAT(COALESCE(SUM(t.Amount),0),' ',g.Active) FROM GiftCard g LEFT JOIN GiftCardTransaction t ON t.GiftCardID=g.GiftCardID WHERE g.GiftCardID"
# A juice line with its one component, its SALE movement and its cost
juice() { echo "$OI ('$1','$2','V1','B1',1,4.00,4.00,0,'TZ',0,0); UPDATE OrderItem SET UnitCost=1, LineCost=1 WHERE OrderItemID='$1'; INSERT INTO OrderItemComponent (OrderItemID,StockItemID,BusinessID,QuantityUsed,StockUnitCode,UnitCost) VALUES ('$1','S1','B1',1,1,1); INSERT INTO InventoryTransaction (InventoryTransactionID,BusinessID,StockItemID,LocationID,QuantityChange,UnitCost,TransactionTypeCode,OrderID) VALUES ('X$1','B1','S1','L1',-1,1,2,'$2');"; }

echo "--- setup ---"
t "business, staff, register"  ok   "INSERT INTO Business (BusinessID,Name) VALUES ('B1','Cafe'),('B2','Shop'); INSERT INTO Location (LocationID,BusinessID,Name,TimeZone,AcceptsOnlineOrders) VALUES ('L1','B1','Main','America/Chicago',1); INSERT INTO Register (RegisterID,LocationID,Name) VALUES ('RG1','L1','Till'); INSERT INTO Role (RoleID,BusinessID,Name,OpensTo,IsOwner) VALUES ('RO1','B1','Owner','REGISTER',1),('RM1','B1','Manager','REGISTER',0),('RS1','B1','Server','REGISTER',0); INSERT INTO RolePermission (RoleID,BusinessID,PermissionCode) VALUES ('RM1','B1',23),('RS1','B1',1); INSERT INTO Employee (EmployeeID,BusinessID,FirstName,LastName,Email,EmployeeNumber,RoleID,Active) VALUES ('E1','B1','O','O','o@x.y','00000001','RO1',1),('E2','B1','M','M','m@x.y','00000002','RM1',1),('E3','B1','S','S','s@x.y','00000003','RS1',1); INSERT INTO EmployeeLocation (EmployeeID,LocationID,BusinessID) VALUES ('E3','L1','B1');"
t "juice, gift card products"  ok   "INSERT INTO TaxCategory (TaxCategoryID,BusinessID,Name) VALUES ('TZ','B1','Exempt'),('TT','B1','Taxed'); INSERT INTO LocationTaxRate (LocationID,TaxCategoryID,BusinessID,Rate) VALUES ('L1','TZ','B1',0),('L1','TT','B1',0.10); INSERT INTO Product (ProductID,BusinessID,Name,IsGiftCard) VALUES ('P1','B1','Juice',0),('PG','B1','Gift card',1); INSERT INTO ProductVariant (VariantID,ProductID,BusinessID,Name,SKU,Price,SellUnitCode,TaxCategoryID) VALUES ('V1','P1','B1','Regular','JUICE',4.00,1,'TZ'),('VG','PG','B1','Regular','GIFT',0,1,'TZ'),('VGT','PG','B1','Taxed','GIFT-T',0,1,'TT'); INSERT INTO StockItem (StockItemID,BusinessID,Name,StockUnitCode) VALUES ('S1','B1','Juice',1); INSERT INTO VariantRecipe (VariantID,StockItemID,BusinessID,QuantityPerUnit) VALUES ('V1','S1','B1',1); INSERT INTO Inventory (InventoryID,LocationID,StockItemID,BusinessID) VALUES ('I1','L1','S1','B1'); INSERT INTO InventoryTransaction (InventoryTransactionID,BusinessID,StockItemID,LocationID,QuantityChange,UnitCost,TransactionTypeCode) VALUES ('T1','B1','S1','L1',100,1,1);"

echo "--- gift card products ---"
t "recipe on a gift card"      fail "INSERT INTO VariantRecipe (VariantID,StockItemID,BusinessID,QuantityPerUnit) VALUES ('VG','S1','B1',1);"
t "options on a gift card"     fail "INSERT INTO ModifierGroup (ModifierGroupID,BusinessID,Name) VALUES ('MG1','B1','Wrap'); INSERT INTO ProductModifierGroup (ProductID,ModifierGroupID,BusinessID) VALUES ('PG','MG1','B1');"
t "juice becomes a gift card"  fail "UPDATE Product SET IsGiftCard=1 WHERE ProductID='P1';"

echo "--- selling a card (G1) ---"
t "order G1"                   ok   "$OR ('G1','L1','B1',1,'RG1','E3',25.00,25.00);"
t "two cards on one line"      fail "$OI ('GL1','G1','VG','B1',2,25.00,50.00,0,'TZ',0,0);"
t "discounted card"            fail "$OI ('GL1','G1','VG','B1',1,25.00,25.00,5.00,'TZ',0,0);"
t "taxed card"                 fail "$OI ('GL1','G1','VGT','B1',1,25.00,25.00,0,'TT',0.10,2.50);"
t "below the minimum"          fail "$OI ('GL1','G1','VG','B1',1,4.00,4.00,0,'TZ',0,0);"
t "above the maximum"          fail "$OI ('GL1','G1','VG','B1',1,600.00,600.00,0,'TZ',0,0);"
t "card line 25.00"            ok   "$OI ('GL1','G1','VG','B1',1,25.00,25.00,0,'TZ',0,0);"
t "pay 25.00 cash"             ok   "$PY ('PA1','G1',1,25.00,3,NULL);"
t "complete without its card"  fail "UPDATE Orders SET OrderStatusCode=5, CompletedAt=NOW() WHERE OrderID='G1';"
t "card of another business"   fail "$GC ('GC0','B2',UNHEX(SHA2('code-0',256)),'0000','GL1');"
t "lower-case last 4"          fail "$GC ('GC0','B1',UNHEX(SHA2('code-0',256)),'ab12','GL1');"
t "card GC1"                   ok   "$GC ('GC1','B1',UNHEX(SHA2('code-1',256)),'1234','GL1');"
t "second card on the line"    fail "$GC ('GC2','B1',UNHEX(SHA2('code-2',256)),'5678','GL1');"
t "hand-written ISSUE"         fail "INSERT INTO GiftCardTransaction (GiftCardTransactionID,GiftCardID,BusinessID,GiftCardTransactionTypeCode,Amount) VALUES ('X1','GC1','B1',1,25.00);"
a "GC1 before completion"           "$BAL='GC1'" "0.00 1"
t "complete G1"                ok   "UPDATE Orders SET OrderStatusCode=5, CompletedAt=NOW() WHERE OrderID='G1';"
a "GC1 issued"                      "$BAL='GC1'" "25.00 1"
t "change the code"            fail "UPDATE GiftCard SET Last4='9999' WHERE GiftCardID='GC1';"

echo "--- spending a card (R1, 4.00) ---"
t "order R1, one juice"        ok   "$OR ('R1','L1','B1',1,'RG1','E3',4.00,4.00); $(juice RL1 R1)"
t "card on a juice line"       fail "$GC ('GCX','B1',UNHEX(SHA2('code-x',256)),'4321','RL1');"
t "gift card method, no card"  fail "$PY ('PR0','R1',3,4.00,3,NULL);"
t "cash method with a card"    fail "$PY ('PR0','R1',1,4.00,3,'GC1');"
t "adjust by a server"         fail "$ADJ ('A1','GC1','B1',5,-22.00,'E3','Damaged');"
t "adjust with no reason"      fail "$ADJ ('A1','GC1','B1',5,-22.00,'E2',NULL);"
t "adjust below zero"          fail "$ADJ ('A1','GC1','B1',5,-30.00,'E2','Damaged');"
t "manager adjusts -22.00"     ok   "$ADJ ('A1','GC1','B1',5,-22.00,'E2','Damaged');"
t "pay 4.00 from 3.00"         fail "$PY ('PR1','R1',3,4.00,3,'GC1');"
t "pay 3.00 by card"           ok   "$PY ('PR1','R1',3,3.00,3,'GC1');"
a "GC1 spent"                       "$BAL='GC1'" "0.00 1"
t "pay 1.00 cash"              ok   "$PY ('PR2','R1',1,1.00,3,NULL);"
t "change the card payment"    fail "UPDATE Payment SET Amount=2.00 WHERE PaymentID='PR1';"
t "delete the card payment"    fail "DELETE FROM Payment WHERE PaymentID='PR1';"
t "complete R1"                ok   "UPDATE Orders SET OrderStatusCode=5, CompletedAt=NOW() WHERE OrderID='R1';"
t "edit the ledger"            fail "UPDATE GiftCardTransaction SET Amount=1 WHERE GiftCardTransactionID='A1';"

echo "--- a card can't buy a card ---"
t "order G2, card line"        ok   "$OR ('G2','L1','B1',1,'RG1','E3',10.00,10.00); $OI ('GL2','G2','VG','B1',1,10.00,10.00,0,'TZ',0,0);"
t "pay G2 with GC1"            fail "$PY ('PG2','G2',3,1.00,1,'GC1');"
t "order R2, pending card pay" ok   "$OR ('R2','L1','B1',1,'RG1','E3',4.00,4.00); $(juice RL2 R2) $PY ('PR3','R2',3,4.00,1,'GC1');"
t "card line after card pay"   fail "$OI ('GL4','R2','VG','B1',1,10.00,10.00,0,'TZ',0,0);"

echo "--- refunds ---"
t "refund 3.00 to the card"    ok   "$RF ('RF1','PR1',NULL,'R1','B1',3.00,0,'Wrong order',2,'E2','E3',NOW());"
a "GC1 refunded"                    "$BAL='GC1'" "3.00 1"
t "change that refund"         fail "UPDATE Refund SET Amount=2.00 WHERE RefundID='RF1';"
t "refund G1, no return"       fail "$RF ('RF2','PA1',NULL,'G1','B1',25.00,0,'Changed mind',2,'E2','E3',NOW());"
t "deactivate GC1"             ok   "UPDATE GiftCard SET Active=0 WHERE GiftCardID='GC1';"
t "spend a deactivated card"   fail "UPDATE Payment SET PaymentStatusCode=3 WHERE PaymentID='PR3';"

echo "--- returning a card ---"
t "return the used GC1"        fail "INSERT INTO Returns (ReturnID,OrderID,BusinessID,ApprovedByEmployeeID,CreatedBy) VALUES ('RT1','G1','B1','E2','E3'); INSERT INTO ReturnItem (ReturnItemID,ReturnID,OrderID,OrderItemID,QuantityReturned) VALUES ('RI1','RT1','G1','GL1',1);"
t "sell GC3 for 10.00"         ok   "$OR ('G3','L1','B1',1,'RG1','E3',10.00,10.00); $OI ('GL3','G3','VG','B1',1,10.00,10.00,0,'TZ',0,0); $GC ('GC3','B1',UNHEX(SHA2('code-3',256)),'3333','GL3'); $PY ('PA3','G3',1,10.00,3,NULL); UPDATE Orders SET OrderStatusCode=5, CompletedAt=NOW() WHERE OrderID='G3';"
t "return the unused GC3"      ok   "INSERT INTO Returns (ReturnID,OrderID,BusinessID,ApprovedByEmployeeID,CreatedBy) VALUES ('RT3','G3','B1','E2','E3'); INSERT INTO ReturnItem (ReturnItemID,ReturnID,OrderID,OrderItemID,QuantityReturned) VALUES ('RI3','RT3','G3','GL3',1);"
a "GC3 cancelled"                   "$BAL='GC3'" "0.00 0"
t "reactivate GC3"             fail "UPDATE GiftCard SET Active=1 WHERE GiftCardID='GC3';"
t "undo the return"            fail "DELETE FROM ReturnItem WHERE ReturnItemID='RI3';"
t "refund G3 on the return"    ok   "$RF ('RF3','PA3','RT3','G3','B1',10.00,0,'Returned card',2,'E2','E3',NOW());"
